// =====================================================================
//  FUXA 表示用データ変換スクリプト
//  Mode: SERVER   Scheduling: Interval 1秒
//
//  [1] 日時        Modbus(Day/Hour/Minute)   → 'DD' / 'HH:MM'     毎回
//  [2] 気温        Modbus(INT 0.01℃)         → number[℃]         WEATHER_EVERY 回に1回
//  [3] 天気記号    Modbus(天気コード UINT)   → 絵文字(String)     WEATHER_EVERY 回に1回
//  [4] API URL     Modbus(地方コード UDINT)　→ URL(String)
//
//  共通ルール
//   - 通信前・通信断(null) と FB の「データ無し」は書き込まず、最後の値を残す
//   - 各ブロックは独立。どこかでエラーが出ても他のブロックは実行される
//   - console.log は SERVER モードでは docker logs fuxa に出る
// =====================================================================


// =====================================================================
//  設定 (タグ名・定数はここだけ直せばよい)
// =====================================================================

// 天気系の処理を何回に1回実行するか (Interval 1秒 × 10 = 10秒ごと)
const WEATHER_EVERY = 10;

// ---- [1] 日時 ----
const DATE_SRC = { day: 'Day', hour: 'Hour', min: 'Minute' };     // Modbus
const DATE_DST = { day2: 'day2digit', hm: 'hourAndMin' };          // 内部(String)

// ---- [2] 気温 ----
const TEMP_DIV  = 100;      // 0.01℃単位なら 100、0.1℃単位なら 10
const TEMP_NONE = -32768;   // FB の「データ無し」(FB側と合わせる)
const TEMP_MAP = [          // [Modbus, 内部(Number)]
    ['TodayTemp',        'temp_1'],   // 今日
    ['TomorrowTemp',     'temp_2'],   // 明日
    ['In2daysLaterTemp', 'temp_3'],   // 明後日
];

// ---- [3] 天気記号 ----
const CODE_NONE = 0;        // FB の「データ無し」
const CODE_MAP = [          // [Modbus, 内部(String)]
    ['TodayCode',        'code_1'],   // 今日
    ['TomorrowCode',     'code_2'],   // 明日
    ['In2daysLaterCode', 'code_3'],   // 明後日
];
// 記号: S晴 C曇 R雨 W雪 X雨か雪 T雷雨 F霧   つなぎ: / 時々・一時   > のち
const ICON = { S:'☀️', C:'☁️', R:'🌧️', W:'⛄', X:'🌨️', T:'⛈️', F:'🌫️' };
const SEP  = { '/':'|', '>':'→' };
const PAT = {
    100:'S', 101:'S/C', 102:'S/R', 103:'S/R', 104:'S/W', 105:'S/W', 106:'S/X', 107:'S/X', 108:'S/T', 110:'S>C',
    111:'S>C', 112:'S>R', 113:'S>R', 114:'S>R', 115:'S>W', 116:'S>W', 117:'S>W', 118:'S>X', 119:'S>T', 120:'S/R',
    121:'S/R', 122:'S/R', 123:'S/T', 124:'S/W', 125:'S>T', 126:'S>R', 127:'S>R', 128:'S>R', 130:'F>S', 131:'F>S',
    132:'S/C', 140:'S/T', 160:'S/X', 170:'S/X', 181:'S>X', 200:'C', 201:'C/S', 202:'C/R', 203:'C/R', 204:'C/W',
    205:'C/W', 206:'C/X', 207:'C/X', 208:'C/T', 209:'F', 210:'C>S', 211:'C>S', 212:'C>R', 213:'C>R', 214:'C>R',
    215:'C>W', 216:'C>W', 217:'C>W', 218:'C>X', 219:'C>T', 220:'C/R', 221:'C/R', 222:'C/R', 223:'C/S', 224:'C>R',
    225:'C>R', 226:'C>R', 228:'C>W', 229:'C>W', 230:'C>W', 231:'C/F', 240:'C/T', 250:'C/T', 260:'C/X', 270:'C/X',
    281:'C>X', 300:'R', 301:'R/S', 302:'R/C', 303:'R/W', 304:'X', 306:'R', 308:'R', 309:'R/W', 311:'R>S',
    313:'R>C', 314:'R>W', 315:'R>W', 316:'X>S', 317:'X>C', 320:'R>S', 321:'R>C', 322:'R/W', 323:'R>S', 324:'R>S',
    325:'R>S', 326:'R>W', 327:'R>W', 328:'R', 329:'R/X', 340:'X', 350:'T', 361:'X>S', 371:'X>C', 400:'W',
    401:'W/S', 402:'W/C', 403:'W/R', 405:'W', 406:'W', 407:'W', 409:'W/R', 411:'W>S', 413:'W>C', 414:'W>R',
    420:'W>S', 421:'W>C', 422:'W>R', 423:'W>R', 425:'W', 426:'W>X', 427:'W/X', 450:'W/T'
};
const FALLBACK = { 1:'S', 2:'C', 3:'R', 4:'W' };   // 表に無いコードは百の位で判断

// ---- [4] API確認用URL ----
const API_ID_SRC  = 'AreaID';     // Modbus(UInt32) PLC に設定中の地点ID
const API_URL_DST = 'apiUrl';     // 内部(String) iframe に紐づけたタグ
const API_URL_FMT = id => `https://weather.tsukumijima.net/api/forecast/city/${String(id).padStart(6, '0')}`;

// =====================================================================
//  共通関数
// =====================================================================

// タグ名で読む。値が無い・数値でないときは null
async function readNum(name) {
    const v = await $getTag($getTagId(name));
    return (v === null || v === undefined || isNaN(Number(v))) ? null : Number(v);
}

// タグ名で書く
function write(name, value) {
    $setTag($getTagId(name), value);
}

// 2桁ゼロ埋め  8 → '08'
function p2(v) {
    return String(Math.trunc(v)).padStart(2, '0');
}

// 天気コード → 絵文字  111 → '☀️→☁️'
function codeToEmoji(code) {
    const c = Math.trunc(code);
    const p = PAT[c] || FALLBACK[Math.floor(c / 100)];
    if (!p) return '?';
    return p.length === 1 ? ICON[p] : ICON[p[0]] + SEP[p[1]] + ICON[p[2]];
}

// ブロックを実行。エラーが出てもログに出して次へ進む
async function runBlock(label, fn) {
    try {
        await fn();
    } catch (e) {
        console.log(`[script] ${label} error: ${e}`);
    }
}


// =====================================================================
//  [1] 日時   (毎回)
// =====================================================================
async function updateDateTime() {
    const day  = await readNum(DATE_SRC.day);
    const hour = await readNum(DATE_SRC.hour);
    const min  = await readNum(DATE_SRC.min);
    if (day === null || hour === null || min === null) return;   // 通信断

    write(DATE_DST.day2, p2(day) + '');               // '08'
    write(DATE_DST.hm,   `${p2(hour)}:${p2(min)}`);   // '14:05'
}


// =====================================================================
//  [2] 気温   (WEATHER_EVERY 回に1回)
// =====================================================================
async function updateTemp() {
    for (const [src, dst] of TEMP_MAP) {
        const n = await readNum(src);
        if (n === null || n === TEMP_NONE) continue;   // 通信断・データ無し
        write(dst, Math.round(n) / TEMP_DIV);          // 1850 → 18.5
    }
}


// =====================================================================
//  [3] 天気記号   (WEATHER_EVERY 回に1回)
// =====================================================================
async function updateWeatherIcon() {
    for (const [src, dst] of CODE_MAP) {
        const n = await readNum(src);
        if (n === null || n === CODE_NONE) continue;   // 通信断・データ無し
        write(dst, codeToEmoji(n));
    }
}

// =====================================================================
//  [4] API確認用URL   (毎回。値が変わったときだけ書き込む)
// =====================================================================
async function updateApiUrl() {
    const id = await readNum(API_ID_SRC);
    if (id === null || id < 1 || id > 999999) return;   // 通信断・不正なID

    const url = API_URL_FMT(Math.trunc(id));            // 16010 → .../016010
    const now = await $getTag($getTagId(API_URL_DST));
    if (now !== url) {
        write(API_URL_DST, url);                        // 変わったときだけ (iframe の再読み込みを防ぐ)
    }
}

// =====================================================================
//  メイン
// =====================================================================
// 実行回数 (SERVER モードではスクリプト実行をまたいで globalThis が残る)
globalThis.__fmtTick = ((globalThis.__fmtTick || 0) + 1) % WEATHER_EVERY;
const weatherTurn = (globalThis.__fmtTick === 1 % WEATHER_EVERY);

await runBlock('datetime', updateDateTime);
if (weatherTurn) {
    await runBlock('temp',    updateTemp);
    await runBlock('weather', updateWeatherIcon);
  	await runBlock('apiurl',   updateApiUrl);
}


// =====================================================================
//  メモ
// =====================================================================
// ・ブロックを足すときは「設定」にタグ名を、「[n] ○○」に関数を書き、メインに1行足す
// ・特定の画面を表示中だけ実行したい場合 (重い処理が増えたら)
//     const panel = await readNum('currentPanel');
//     if (panel === 2) { await runBlock('xxx', updateXxx); }
// ・デバッグ: Test ボタンで実行し、下の Console で確認
//     console.log(JSON.stringify({ day: await readNum('Day') }));
